def card(task, wd):
    parts = []
    for i, c in enumerate(['black', 'white', '0x3040c0']):
        parts.append(fx.color_clip(Path(wd) / ('c%d.mp4' % i), c, 1.0, '160x90'))
    lst = tw(Path(wd) / 'list.txt', ''.join(("file '%s'\n" % p for p in parts)))
    src = Path(wd) / 'cuts.mp4'
    fx.ffmpeg('-f', 'concat', '-safe', '0', '-i', lst, '-c', 'copy', src)

    def cuts(p):
        e = subprocess.run(['ffmpeg', '-hide_banner', '-i', str(p), '-vf', "select='gt(scene,0.3)',showinfo", '-f', 'null', '-'], capture_output=True, text=True, timeout=60).stderr
        return [round(float(t), 3) for t in re.findall('pts_time:([0-9.]+)', e)]
    got = cuts(src)
    out = jw(Path(wd) / 'scenes.json', {'cuts_s': got, 'threshold': 0.3})
    return ([check('two cuts found at 1.0 s and 2.0 s', len(got) == 2 and abs(got[0] - 1) < 0.05 and (abs(got[1] - 2) < 0.05), got, [1.0, 2.0]), check('negative control: a single-colour clip has no cut', cuts(parts[0]) == [], cuts(parts[0]))], [out])

