def card(work):
    scene = {'layout': 'split', 'palette': 'night', 'type': 'Cairo', 'tempo': 1.0}
    h0 = sha256(json.dumps(scene, sort_keys=True).encode())
    base, sibs = fan_out(scene, {'palette': 'dawn', 'type': 'Tajawal', 'tempo': 1.25}, work)
    diffs = []
    for d in sibs:
        v = json.loads((d / 'scene.json').read_text())
        diffs.append([k for k in scene if scene[k] != v[k]])
    return [('original untouched', sha256((base / 'scene.json').read_bytes()) == h0, h0[:12]), ('three sibling folders, side by side', sorted((d.name for d in sibs)) == ['scene--palette', 'scene--tempo', 'scene--type'], [d.name for d in sibs]), ('each sibling changes exactly its named axis', diffs == [['palette'], ['type'], ['tempo']], diffs)]

